var a=`1098-tam-mak-hoong`;var n=`world-1098`;var t=`LA`;var s=`southeast-asia`;var o=4;var r=25;var g={en:`Tam Mak Hoong`,ua:`Там мак хунг`};var l={en:`Tam Mak Hoong is a dish from Laos prepared with papaya, carrot, garlic, bird's eye chili. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Там мак хунг, страва кухні країни Лаос, яку готують із таких продуктів: папая, морква, часник, перець чилі пташине око. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var m=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:12,i:[[`papaya`,530,`g`],[`carrot`,140,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`garlic`,4,`clove`],[`bird-s-eye-chili`,3,`pcs`],[`fish-sauce`,40,`ml`],[`lime-juice`,60,`ml`],[`palm-sugar`,25,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`tomato`,210,`g`],[`green-beans`,130,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`peanut`,80,`g`]]}];var d={slug:a,id:n,country:`LA`,region:s,servings:4,minutes:25,title:g,text:l,steps:m};export{t as country,d as default,n as id,r as minutes,s as region,o as servings,a as slug,m as steps,l as text,g as title};